rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c_list_size/{doc} {
      allow get: if [1, 2, 3].size() == 3;
    }
    match /c_list_hasall_empty/{doc} {
      allow get: if [1, 2].hasAll([]);
    }
    match /c_list_hasany_empty/{doc} {
      allow get: if [].hasAny([]);
    }
    match /c_list_hasonly/{doc} {
      allow get: if [1, 2].hasOnly([1, 2, 3]);
    }
    match /c_list_hasonly_dupes/{doc} {
      allow get: if [1, 1].hasOnly([1]);
    }
    match /c_list_plus/{doc} {
      allow get: if [1, 2] + [3] == [1, 2, 3];
    }
    match /c_list_removeall/{doc} {
      allow get: if [1, 2, 1].removeAll([1]) == [2];
    }
    match /c_list_index_out_of_range/{doc} {
      allow get: if [1, 2, 3][5] == 1;
    }
    match /c_list_index_negative/{doc} {
      allow get: if [1, 2, 3][-1] == 3;
    }
    match /c_list_range/{doc} {
      allow get: if [1, 2, 3][0:2] == [1, 2];
    }
    match /c_list_range_past_end/{doc} {
      allow get: if [1, 2, 3][1:9] == [2, 3];
    }
    match /c_list_join/{doc} {
      allow get: if ['a', 'b'].join(',') == 'a,b';
    }
    match /c_list_join_ints/{doc} {
      allow get: if [1, 2].join(',') == '1,2';
    }
    match /c_list_order_matters/{doc} {
      allow get: if [1, 2] == [2, 1];
    }
    match /c_list_mixed_types/{doc} {
      allow get: if [1, 'a', null].size() == 3;
    }
    match /c_list_neg_zero/{doc} {
      allow get: if [0.0] == [-0.0];
    }
    match /c_list_hasall_in_float/{doc} {
      allow get: if [1].hasAll([1.0]);
    }
    match /c_list_in_map/{doc} {
      allow get: if {'a': 1} in [{'a': 1}];
    }
    match /c_set_eq/{doc} {
      allow get: if [1, 2, 2].toSet() == [2, 1].toSet();
    }
    match /c_set_in_float/{doc} {
      allow get: if 1 in [1.0].toSet();
    }
    match /c_set_int_float_dedupe/{doc} {
      allow get: if [1, 1.0].toSet().size() == 1;
    }
    match /c_set_difference/{doc} {
      allow get: if [1, 2].toSet().difference([2].toSet()) == [1].toSet();
    }
    match /c_set_intersection/{doc} {
      allow get: if [1, 2].toSet().intersection([2, 3].toSet()) == [2].toSet();
    }
    match /c_set_hasonly/{doc} {
      allow get: if [1, 2].toSet().hasOnly([1, 2, 3]);
    }
    match /c_set_eq_list/{doc} {
      allow get: if [1].toSet() == [1];
    }
    match /c_map_keys/{doc} {
      allow get: if {'a': 1}.keys() == ['a'];
    }
    match /c_map_values/{doc} {
      allow get: if {'a': 1}.values() == [1];
    }
    match /c_map_keys_order_sorted/{doc} {
      allow get: if {'b': 1, 'a': 2}.keys() == ['a', 'b'];
    }
    match /c_map_keys_order_insertion/{doc} {
      allow get: if {'b': 1, 'a': 2}.keys() == ['b', 'a'];
    }
    match /c_map_values_order/{doc} {
      allow get: if {'b': 1, 'a': 2}.values() == [2, 1];
    }
    match /c_map_size/{doc} {
      allow get: if {'a': 1, 'b': 2}.size() == 2;
    }
    match /c_map_in_key/{doc} {
      allow get: if 'a' in {'a': 1};
    }
    match /c_map_get/{doc} {
      allow get: if {'a': 1}.get('a', 0) == 1;
    }
    match /c_map_get_default/{doc} {
      allow get: if {'a': 1}.get('b', 0) == 0;
    }
    match /c_map_get_path/{doc} {
      allow get: if {'a': {'b': 1}}.get(['a', 'b'], 0) == 1;
    }
    match /c_map_get_path_through_int/{doc} {
      allow get: if {'a': 1}.get(['a', 'b'], 0) == 0;
    }
    match /c_map_get_empty_path/{doc} {
      allow get: if {'a': 1}.get([], 0) == 0;
    }
    match /c_map_get_int_key/{doc} {
      allow get: if {'a': 1}.get(1, 0) == 0;
    }
    match /c_map_missing/{doc} {
      allow get: if {'a': 1}.b == 1;
    }
    match /c_map_eq/{doc} {
      allow get: if {'a': 1, 'b': 2} == {'b': 2, 'a': 1};
    }
    match /c_map_hasall_direct/{doc} {
      allow get: if {'a': 1}.hasAll(['a']);
    }
    match /c_doc_keys_hasonly/{doc} {
      allow get: if resource.data.keys().hasOnly(['n', 'f', 's', 'b', 'nul', 'arr', 'tags', 'm', 'owner']);
    }
    match /c_diff_affected/{doc} {
      allow get: if {'a': 1, 'b': 2}.diff({'a': 1, 'b': 3, 'c': 4}).affectedKeys() == ['b', 'c'].toSet();
    }
    match /c_diff_added/{doc} {
      allow get: if {'a': 1}.diff({'a': 1, 'c': 4}).addedKeys() == ['c'].toSet();
    }
    match /c_diff_removed/{doc} {
      allow get: if {'a': 1, 'c': 4}.diff({'a': 1}).removedKeys() == ['c'].toSet();
    }
    match /c_diff_changed/{doc} {
      allow get: if {'a': 1}.diff({'a': 2}).changedKeys() == ['a'].toSet();
    }
    match /c_diff_unchanged/{doc} {
      allow get: if {'a': 1, 'b': 2}.diff({'a': 1, 'b': 3}).unchangedKeys() == ['a'].toSet();
    }
    match /c_diff_int_float_changed/{doc} {
      allow get: if {'a': 1}.diff({'a': 1.0}).changedKeys().size() == 0;
    }
    match /c_diff_nested/{doc} {
      allow get: if {'m': {'x': 1}}.diff({'m': {'x': 2}}).affectedKeys() == ['m'].toSet();
    }
    match /c_diff_not_map/{doc} {
      allow get: if {'a': 1}.diff([1]).affectedKeys().size() == 0;
    }
    match /c_diff_on_update/{doc} {
      allow update: if request.resource.data.diff(resource.data).affectedKeys() == ['b', 'c', 'm'].toSet();
    }
    match /c_diff_on_update_hasonly/{doc} {
      allow update: if request.resource.data.diff(resource.data).affectedKeys().hasOnly(['b', 'c', 'm']);
    }
  }
}

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c_map_duplicate_key/{doc} {
      allow get: if {'a': 1, 'a': 2}.a == 2;
    }
  }
}

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c_map_int_key/{doc} {
      allow get: if {1: 2}.size() == 1;
    }
  }
}
